import { ISessionManagementEvents, ISessionManagementProgressTranslations, ISessionStatus } from '../../types';
import { Component, Inject, Prop, Vue, Watch } from 'vue-property-decorator';
import AcceptPopup from '../accept-popup/index.vue';
import EventEmitter from 'eventemitter3';

@Component({
    components: { AcceptPopup },
})
export default class ProgressDetails extends Vue {
    @Inject()
    public readonly events: EventEmitter<ISessionManagementEvents>;

    @Prop()
    public readonly translations: ISessionManagementProgressTranslations;

    @Prop()
    public readonly sessionStatus: ISessionStatus;

    @Prop()
    public readonly sessionDuration: number;

    @Prop()
    public readonly suppressed: boolean;

    @Prop()
    public readonly hasLowBalance: boolean;

    @Inject()
    public readonly stringifyTime: (seconds: number) => string;

    @Inject()
    public readonly stringifyBet: (bet: number) => string;

    private progressAlertTime: number = -1;

    get visible(): boolean {
        return (!this.suppressed && !this.sessionStatus.SessionEnded && (this.progressAlertTime <= this.sessionDuration));
    }

    get netBalance(): string {
        return this.stringifyBet(this.sessionStatus.NetBalance);
    }

    get timeSpent(): string {
        return this.stringifyTime(this.sessionDuration);
    }

    public onClose(): void {
        this.calculateProgressAlertTime();
    }

    @Watch('sessionStatus', { immediate: true, deep: true })
    public onSessionStatusChanged(): void {
        if (!this.sessionStatus.SessionEnded) {
            this.calculateInitialProgressAlertTime();
        } else {
            this.progressAlertTime = -1;
        }
    }

    @Watch('visible', { immediate: true })
    public onVisible(): void {
        if (this.visible) {
            this.$emit('alert');
        }
    }

    private calculateInitialProgressAlertTime(): void {
        if (this.progressAlertTime < 0) {
            const alertFrequency = this.sessionStatus.AlertFrequency;
            const currentSessionDuration = this.sessionDuration;

            const nextAlertIterationTime = (Math.floor(currentSessionDuration / alertFrequency) + 1) * alertFrequency;

            this.progressAlertTime = nextAlertIterationTime;
        }
    }

    private calculateProgressAlertTime(): void {
        this.progressAlertTime = this.sessionDuration + this.sessionStatus.AlertFrequency;
    }
}